using System;using System.Linq;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 public sealed class MobileShell:MonoBehaviour {
  Button[] navigation;Image[] surfaces;Text[][] labels;string selection;readonly string[] names={"hardware","research","items","prestige","shop"};public Button ShopTab {get;private set;}bool prestigeVisible;string language;
  Image indicator;float indicatorX;bool located;GameRuntime game;public Sprite[] ResourceIcons;public LaboratoryView Laboratory;public void Initialize(GameRuntime runtime){game=runtime;game.TrainingTab.gameObject.SetActive(false);ShopTab=Instantiate(game.ItemsTab,game.ItemsTab.transform.parent);ShopTab.name="ShopTab";ShopTab.onClick.RemoveAllListeners();ShopTab.onClick.AddListener(()=>game.UserShow("shop"));ShopTab.transform.Find("NavigationIcon").GetComponent<Image>().sprite=game.Users.transform.parent.Find("ResourceIcon").GetComponent<Image>().sprite;navigation=new[]{game.HardwareTab,game.ResearchTab,game.ItemsTab,game.PrestigeTab,ShopTab};for(int i=0;i<navigation.Length;i++)navigation[i].transform.SetSiblingIndex(i);surfaces=navigation.Select(b=>b.GetComponent<Image>()).ToArray();labels=navigation.Select(b=>b.GetComponentsInChildren<Text>()).ToArray();foreach(var b in navigation){var line=b.transform.Find("ActiveLine");if(line!=null)line.gameObject.SetActive(false);}var receipts=gameObject.AddComponent<RewardPresentation>();receipts.Initialize(game);Laboratory.Initialize(game);var menu=gameObject.AddComponent<GameMenu>();menu.Initialize(game);var safe=Laboratory.GetComponentInParent<SafeArea>().transform;var tabs=safe.Find("Tabs");indicator=WorkshopUIFactory.Node("ActiveNavigationMarker",tabs,typeof(Image),typeof(LayoutElement)).GetComponent<Image>();indicator.GetComponent<LayoutElement>().ignoreLayout=true;indicator.raycastTarget=false;indicator.color=GameTheme.Accent;indicator.rectTransform.anchorMin=indicator.rectTransform.anchorMax=new Vector2(.5f,0);indicator.rectTransform.sizeDelta=new Vector2(52,3);var button=safe.Find("Resources/Menu")??safe.Find("Header/Menu");if(button!=null)button.GetComponent<Button>().onClick.AddListener(menu.Open);}
  public void RefreshNavigation()=>LateUpdate();
  void LateUpdate(){if(game?.State==null)return;var s=game.State;bool unlocked=ProgressionVisibility.Prestige(s);if(prestigeVisible!=unlocked||game.PrestigeTab.gameObject.activeSelf!=unlocked){prestigeVisible=unlocked;game.PrestigeTab.gameObject.SetActive(unlocked);located=false;}if(language!=s.Settings.language){language=s.Settings.language;for(int i=0;i<5;i++)navigation[i].GetComponentInChildren<Text>().text=NavigationWords.Label(names[i],language);}string route=game.NavigationTab=="training"?"hardware":game.NavigationTab=="models"?"research":new[]{"market","gems","store","ads"}.Contains(game.NavigationTab)?"shop":game.NavigationTab;string selected=Array.IndexOf(names,route)>=0?route:"hardware";int index=Array.IndexOf(names,selected);if(selection!=selected){selection=selected;for(int i=0;i<5;i++){bool active=i==index;surfaces[i].color=active?GameTheme.Hex("17353F"):Color.clear;foreach(var text in labels[i])text.color=active?GameTheme.Accent:GameTheme.Muted;}}bool lab=game.CurrentTab=="hardware";if(Laboratory.gameObject.activeSelf!=lab)Laboratory.gameObject.SetActive(lab);if(indicator!=null){var parent=(RectTransform)indicator.transform.parent;float goal=parent.InverseTransformPoint(navigation[index].transform.position).x;bool reduced=s.Workshop.reducedMotion||!s.Settings.effects;if(!located||reduced||Mathf.Abs(goal-indicatorX)<.1f)indicatorX=goal;else indicatorX=Mathf.Lerp(indicatorX,goal,1-Mathf.Exp(-Time.unscaledDeltaTime*20));located=true;indicator.rectTransform.anchoredPosition=new Vector2(Mathf.Round(indicatorX),3);indicator.rectTransform.sizeDelta=new Vector2(((RectTransform)navigation[index].transform).rect.width-20,3);}}
 }
}
